<script setup lang="ts">import{onMounted,ref}from'vue';import{useRouter}from'vue-router';import{listVersions}from'@/api/versions';import{useResponsive}from'@/composables/useResponsive';import StatusTag from'@/components/StatusTag.vue';const router=useRouter();const{isMobile}=useResponsive();const rows=ref<any[]>([]);onMounted(async()=>rows.value=(await listVersions()).items)</script>
<template><div class="page"><div class="page-title">版本管理</div><el-table v-if="!isMobile" :data="rows"><el-table-column prop="version_no" label="版本号"/><el-table-column prop="name" label="版本名称"/><el-table-column label="状态"><template #default="s"><StatusTag :status="s.row.status"/></template></el-table-column><el-table-column prop="planned_release_date" label="计划上线"/><el-table-column label="操作"><template #default="s"><el-link type="primary" @click="router.push('/versions/'+s.row.id)">查看</el-link></template></el-table-column></el-table><div v-else class="cards"><el-card v-for="r in rows" :key="r.id" @click="router.push('/versions/'+r.id)"><b>{{r.version_no}} {{r.name}}</b><div class="meta"><span>{{r.planned_release_date||'-'}}</span><StatusTag :status="r.status"/></div></el-card></div></div></template><style scoped>.cards{display:grid;gap:10px}.meta{display:flex;justify-content:space-between;margin-top:10px}</style>
